application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600&display=swap');

:root { --ink:#202b35; --muted:#77828d; --accent:#4f7d70; --accent-dark:#376257; --line:#e8ece9; --paper:#fff; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; color:var(--ink); font-family:'DM Sans',sans-serif; background:linear-gradient(135deg,#edf4f0 0%,#f7f5ef 100%); }
.app-shell { width:min(100% - 32px, 620px); margin:0 auto; padding:clamp(42px,10vh,100px) 0 28px; }
.todo-card { background:var(--paper); border:1px solid rgba(54,82,69,.08); border-radius:24px; padding:clamp(25px,6vw,44px); box-shadow:0 20px 55px rgba(39,62,52,.11); }
.app-header { display:flex; gap:16px; align-items:center; margin-bottom:31px; }
.brand-mark { display:grid; place-items:center; width:47px; height:47px; border-radius:15px; color:#fff; font-size:25px; font-weight:700; background:var(--accent); box-shadow:0 7px 15px rgba(79,125,112,.23); }
.eyebrow { margin:0 0 3px; color:var(--accent); font-size:11px; font-weight:700; letter-spacing:1.7px; text-transform:uppercase; }
h1,h2 { margin:0; } h1 { font-family:'Playfair Display',serif; font-size:clamp(28px,5vw,36px); line-height:1.1; } h2 { font-size:17px; }
.task-form { display:flex; gap:10px; margin-bottom:35px; }
.task-form input { min-width:0; flex:1; padding:14px 16px; border:1px solid #dce4df; border-radius:11px; outline:none; color:var(--ink); font:inherit; background:#fbfcfb; transition:.2s; }
.task-form input:focus { border-color:var(--accent); box-shadow:0 0 0 3px rgba(79,125,112,.13); }
.task-form button { border:0; border-radius:11px; padding:0 17px; color:#fff; background:var(--accent); cursor:pointer; font:600 14px 'DM Sans',sans-serif; transition:.2s; }
.task-form button:hover { background:var(--accent-dark); transform:translateY(-1px); } .task-form button span { margin-left:6px; font-size:18px; vertical-align:-1px; }
.list-heading { display:flex; align-items:center; justify-content:space-between; padding-bottom:13px; border-bottom:1px solid var(--line); }
.count-pill { padding:5px 10px; color:var(--accent-dark); border-radius:20px; background:#edf5f1; font-size:12px; font-weight:600; }
.task-list { display:flex; flex-direction:column; }
.task-item { display:flex; align-items:center; gap:13px; min-height:63px; border-bottom:1px solid var(--line); animation:appear .22s ease-out; }
@keyframes appear { from { opacity:0; transform:translateY(-5px); } to { opacity:1; transform:none; } }
.complete-button { flex:0 0 auto; width:21px; height:21px; padding:0; border:1.5px solid #b8c8c0; border-radius:50%; background:#fff; cursor:pointer; position:relative; }
.task-item.completed .complete-button { border-color:var(--accent); background:var(--accent); } .task-item.completed .complete-button::after { content:'✓'; position:absolute; inset:0; color:#fff; font-size:14px; line-height:18px; }
.task-text { flex:1; overflow-wrap:anywhere; font-size:15px; line-height:1.45; } .task-item.completed .task-text { color:#9ba5a0; text-decoration:line-through; text-decoration-thickness:1.5px; }
.delete-button { padding:7px; border:0; color:#aab4af; background:transparent; cursor:pointer; font-size:20px; line-height:1; opacity:0; transition:.2s; }
.task-item:hover .delete-button, .delete-button:focus { opacity:1; } .delete-button:hover { color:#bd6d64; }
.empty-state { margin:28px 0 3px; color:var(--muted); text-align:center; font-size:14px; } .footer-note { margin:20px 0 0; color:#87958e; text-align:center; font-size:12px; }
.sr-only { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0; }
@media (max-width:460px) { .task-form { flex-direction:column; } .task-form button { min-height:46px; } .delete-button { opacity:1; } }

application.javascript:
const form = document.getElementById('task-form');
const input = document.getElementById('task-input');
const list = document.getElementById('task-list');
const emptyState = document.getElementById('empty-state');
const count = document.querySelector('[data-testid="incomplete-count"]');
const countLabel = document.getElementById('count-label');
let tasks = [];

function render() {
  list.replaceChildren();
  tasks.forEach(task => {
    const item = document.createElement('div');
    item.className = `task-item${task.completed ? ' completed' : ''}`;
    item.dataset.testid = 'task';
    item.dataset.completed = String(task.completed);

    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'complete-button';
    toggle.dataset.testid = 'task-complete';
    toggle.setAttribute('aria-label', task.completed ? `Mark ${task.text} as incomplete` : `Mark ${task.text} as complete`);
    toggle.setAttribute('aria-pressed', String(task.completed));
    toggle.addEventListener('click', () => {
      task.completed = !task.completed;
      render();
    });

    const text = document.createElement('span');
    text.className = 'task-text';
    text.dataset.testid = 'task-text';
    text.textContent = task.text;

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.dataset.testid = 'task-delete';
    remove.setAttribute('aria-label', `Delete ${task.text}`);
    remove.textContent = '×';
    remove.addEventListener('click', () => {
      tasks = tasks.filter(entry => entry.id !== task.id);
      render();
    });

    item.append(toggle, text, remove);
    list.appendChild(item);
  });
  const remaining = tasks.filter(task => !task.completed).length;
  count.textContent = remaining;
  countLabel.textContent = remaining === 1 ? 'remaining' : 'remaining';
  emptyState.hidden = tasks.length > 0;
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) {
    input.focus();
    return;
  }
  tasks.push({ id: Date.now() + Math.random(), text, completed: false });
  input.value = '';
  render();
  input.focus();
});

render();
